&lt;script&gt;
(function() {
  const boxId = &#34;bili-%!s(int=115185486402704)-1784127350960247000&#34;;
  const box = document.getElementById(boxId);
  if (!box) { console.error(&#39;Bili Error: Box not found&#39;, boxId); return; }

  const wrapper = box.querySelector(&#39;.poster-wrapper&#39;);
  const iframe = box.querySelector(&#39;iframe&#39;);


  console.log(`Bili Ready: ${boxId}`, { 
    title: &#34;这就是我和掷面虫热血沸腾的组合技口牙&#34;, 
    pic: &#34;https:\/\/i1.hdslb.com\/bfs\/archive\/9f131ef184537a429c37dc6f1b6e08ac6ccbe203.jpg&#34; 
  });

  wrapper.addEventListener(&#39;click&#39;, function() {
    console.log(`Bili Clicked: ${boxId}`);


    const realSrc = iframe.getAttribute(&#39;data-src&#39;);
    if (!realSrc) {
        console.error(&#39;Bili Error: No data-src found&#39;);
        return;
    }


    if (!iframe.src || iframe.src === window.location.href) {

        const finalSrc = realSrc.startsWith(&#39;//&#39;) ? &#39;https:&#39; + realSrc : realSrc;
        console.log(&#39;Loading Iframe:&#39;, finalSrc);
        iframe.src = finalSrc;
    }


    box.classList.add(&#39;is-active&#39;);
  }, { once: true }); 
})();
&lt;/script&gt;&lt;/p&gt;
